ebbol kuldj vissza egy css sablont: <!DOCTYPE html>
<html lang="hu">
<head>
    <meta charset="UTF8">
    <meta name="viewport" content="width=devicewidth, initialscale=1.0, maximumscale=1.0, userscalable=no, viewportfit=cover, interactivewidget=resizescontent">
    <title>JADED  Deep Discovery AI Platform</title>

    <meta name="applemobilewebappcapable" content="yes">
    <meta name="applemobilewebappstatusbarstyle" content="blacktranslucent">
    <meta name="applemobilewebapptitle" content="JADED">
    <meta name="mobilewebappcapable" content="yes">
    <meta name="themecolor" content="000000">
    <meta name="appletouchfullscreen" content="yes">
    <meta name="formatdetection" content="telephone=no">

    <link rel="appletouchicon" sizes="180x180" href="image/svg+xml,%3Csvg xmlns='' viewBox='0 0 100 100'%3E%3Crect width='100' height='100' fill='%23000' rx='22'/%3E%3Cpath d='M 30 28 C 30 50 50 72 70 72' stroke='white' strokewidth='8' fill='none' strokelinecap='round'/%3E%3Ccircle cx='30' cy='72' r='6' fill='white'/%3E%3C/svg%3E">

    <link rel="manifest" href="application/manifest+json,%7B%22name%22%3A%22JADED%20%20Deep%20Discovery%20AI%20Platform%22%2C%22short_name%22%3A%22JADED%22%2C%22description%22%3A%22Fejlett%20AI%20platform%20tudom%C3%A1nyos%20szolg%C3%A1ltat%C3%A1sokkal%22%2C%22start_url%22%3A%22%2F%22%2C%22display%22%3A%22standalone%22%2C%22orientation%22%3A%22portraitprimary%22%2C%22theme_color%22%3A%22%23000000%22%2C%22background_color%22%3A%22%23000000%22%2C%22scope%22%3A%22%2F%22%2C%22lang%22%3A%22hu%22%2C%22categories%22%3A%5B%22science%22%2C%22utilities%22%5D%7D">

    <style>
        @import url('');

        :root {
            primary: 0A61F7; 
            secondary: 39FF14; 
            accent: 0A61F7;
            borderglow: rgba(10, 97, 247, 0.5); 
            primaryrgb: 10, 97, 247; 
            secondaryrgb: 57, 255, 20;
            bg: 000000; 
            surface: rgba(10, 10, 10, 0.7); 
            glass: rgba(255, 255, 255, 0.02);
            glassstrong: rgba(255, 255, 255, 0.05); 
            border: rgba(255, 255, 255, 0.08);
            text: f0f0f0; 
            textmuted: 94a3b8; 
            radiuslg: 24px; 
            radiusmd: 16px; 
            radiussm: 12px;
            shadow: 0 12px 48px rgba(0, 0, 0, 0.6);
            transitioncurve: cubicbezier(0.25, 0.8, 0.25, 1); 
            transitioncolorslow: 15s easeinout;
        }
         { margin: 0; padding: 0; boxsizing: borderbox; webkittaphighlightcolor: transparent; }
        html { height: 100%; height: webkitfillavailable; scrollbehavior: smooth; }
        body {
            fontfamily: 'Inter', sansserif; background: var(bg); color: var(text);
            minheight: 100vh; minheight: webkitfillavailable; overflow: hidden;
            webkitfontsmoothing: antialiased; fontsize: 15px;
        }
        .aurorabackground { position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; pointerevents: none; zindex: 1; overflow: hidden; willchange: transform; }
        .aurora { position: absolute; borderradius: 50%; mixblendmode: screen; filter: blur(120px); opacity: 0; transition: backgroundcolor var(transitioncolorslow), opacity 8s easeinout; animation: pulse 30s easeinout infinite alternate; willchange: transform, opacity; }
        .aurora.visible { opacity: 0.3; }
        .aurora.one { width: 80vmax; height: 80vmax; animationname: moveone, pulse; animationduration: 1200s, 35s; animationtimingfunction: linear, easeinout; animationiterationcount: infinite, infinite; animationdirection: alternate, alternate; }
        .aurora.two { width: 70vmax; height: 70vmax; animationname: movetwo, pulse; animationduration: 1050s, 40s; animationtimingfunction: linear, easeinout; animationiterationcount: infinite, infinite; animationdirection: alternate, alternate; }
        @keyframes moveone { from { transform: translate(20vw, 20vh) scale(1); } to { transform: translate(50vw, 80vh) scale(1.2); } }
        @keyframes movetwo { from { transform: translate(80vw, 30vh) scale(1); } to { transform: translate(10vw, 60vh) scale(1.3); } }
        @keyframes pulse { from { opacity: 0.2; } to { opacity: 0.4; } }
        .container { display: flex; minheight: 100vh; minheight: webkitfillavailable; position: relative; }

        .welcometitle, .modaltitle, .headertitle { background: lineargradient(135deg, var(primary), var(secondary)); webkitbackgroundclip: text; webkittextfillcolor: transparent; }
        .headertitle { textshadow: 0 0 15px var(borderglow); fontsize: 1.2rem; }
        .categorytitle i, .accent { color: var(accent); }
        .serviceitem:hover { borderleftcolor: var(primary); }

        .sidebar { width: 260px; background: var(surface); backdropfilter: blur(60px) saturate(180%); borderright: 1px solid var(border); overflowx: hidden; position: fixed; height: 100vh; height: webkitfillavailable; zindex: 1000; transform: translateX(100%); transition: transform 0.4s var(transitioncurve); display: flex; flexdirection: column; willchange: transform; }
        .sidebar.open { transform: translateX(0); }
        .sidebaroverlay { position: fixed; top: 0; left: 0; width: 100vw; height: 100vh; background: rgba(0, 0, 0, 0.5); backdropfilter: blur(10px); zindex: 999; opacity: 0; visibility: hidden; transition: opacity 0.4s ease, visibility 0.4s ease; willchange: opacity; }
        .sidebaroverlay.active { opacity: 1; visibility: visible; }
        .sidebarheader { padding: 12px; borderbottom: 1px solid var(border); }
        .logo { display: flex; alignitems: center; gap: 10px; marginbottom: 12px; }
        .logoicon { width: 28px; height: 28px; transition: transform 0.3s var(transitioncurve); }
        .logo:hover .logoicon { transform: scale(1.15) rotate(10deg); }
        .logotext h1 { fontsize: 1.1rem; fontweight: 700; lineheight: 1.1; background: lineargradient(135deg, var(primary), var(secondary)); webkitbackgroundclip: text; webkittextfillcolor: transparent; }
        .logotext p { fontsize: 0.7rem; color: var(textmuted); margintop: 1px; fontweight: 500; }
        .newchatbtn { width: 100%; background: var(glassstrong); border: 1px solid var(border); color: var(text); borderradius: var(radiusmd); padding: 8px 10px; fontweight: 600; fontsize: 0.8rem; cursor: pointer; display: flex; alignitems: center; justifycontent: center; gap: 6px; transition: all 0.2s var(transitioncurve); }
        .newchatbtn:hover { transform: translateY(2px); bordercolor: var(borderglow); boxshadow: 0 4px 15px 5px rgba(0,0,0,0.4), 0 0 10px 5px var(borderglow); }
        .sidebarcontent { padding: 12px; flexgrow: 1; overflowy: auto; }
        .sidebarfooter { padding: 12px; bordertop: 1px solid var(border); }
        .madeby { fontsize: 0.7rem; color: var(textmuted); textalign: center; }
        .servicecategory { marginbottom: 12px; }
        .categoryheader { background: var(glass); border: 1px solid var(border); borderradius: var(radiussm); padding: 8px 10px; cursor: pointer; display: flex; alignitems: center; justifycontent: spacebetween; marginbottom: 4px; transition: all 0.2s var(transitioncurve); minheight: 40px; }
        .categoryheader .fachevrondown { transition: transform 0.3s var(transitioncurve); }
        .categoryheader:hover { background: var(glassstrong); bordercolor: var(borderglow); transform: translateY(1px); }
        .categorytitle { display: flex; alignitems: center; gap: 8px; fontweight: 600; fontsize: 0.8rem; }
        .categoryservices { display: grid; gridtemplaterows: 0fr; transition: gridtemplaterows 0.4s easeout; }
        .categoryservices > div { overflow: hidden; }
        .categoryservices.open { gridtemplaterows: 1fr; }
        .serviceitem { background: transparent; border: 1px solid transparent; borderradius: var(radiussm); padding: 8px 10px; marginbottom: 4px; cursor: pointer; transition: all 0.2s var(transitioncurve); display: flex; alignitems: center; gap: 8px; marginleft: 6px; borderleft: 2px solid var(border); minheight: 44px; }
        .serviceitem:hover { background: var(glassstrong); bordercolor: transparent transparent transparent var(primary); transform: translateX(4px); color: fff; }
        .serviceicon { width: 28px; height: 28px; background: var(glassstrong); border: 1px solid var(border); borderradius: var(radiussm); display: flex; alignitems: center; justifycontent: center; fontsize: 0.9rem; flexshrink: 0; color: var(accent); transition: all 0.3s var(transitioncurve); boxshadow: 0 2px 6px rgba(0, 0, 0, 0.3); }
        .serviceitem:hover .serviceicon { transform: scale(1.1) rotate(5deg); boxshadow: 0 4px 10px var(borderglow); bordercolor: var(borderglow); }
        .serviceinfo h4 { fontsize: 0.8rem; fontweight: 600; marginbottom: 2px; }
        .serviceinfo p { fontsize: 0.7rem; color: var(textmuted); }

        .maincontent { flex: 1; marginleft: 0; display: flex; flexdirection: column; transition: marginleft 0.4s var(transitioncurve); minheight: 100vh; minheight: webkitfillavailable; maxheight: 100vh; maxheight: webkitfillavailable; overflow: hidden; }
        .header { padding: 8px 12px; height: 48px; background: var(surface); backdropfilter: blur(60px) saturate(180%); borderbottom: 1px solid var(border); display: flex; alignitems: center; justifycontent: spacebetween; position: sticky; top: 0; zindex: 100; }
        .menutoggle { background: var(glassstrong); border: 1px solid var(border); borderradius: var(radiussm); padding: 6px; color: var(text); cursor: pointer; transition: all 0.2s var(transitioncurve); fontsize: 0.9rem; width: 36px; height: 36px; display: flex; alignitems: center; justifycontent: center; }
        .menutoggle:hover { background: var(glassstrong); bordercolor: var(borderglow); transform: scale(1.05); }
        .chatarea { flex: 1; display: flex; flexdirection: column; overflowy: auto; }
        .messagescontainer { padding: 12px; overflowy: auto; flex: 1; }
        .welcomescreen { textalign: center; maxwidth: 500px; margin: 0 auto; padding: 30px 20px; display: flex; flexdirection: column; alignitems: center; justifycontent: center; height: 100%; animation: fadeIn 1s var(transitioncurve); }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(15px); } to { opacity: 1; transform: translateY(0); } }
        .welcometitle { fontsize: 2.2rem; marginbottom: 0.5rem; fontweight: 800; }
        .welcomesubtitle { fontsize: 0.9rem; lineheight: 1.5; marginbottom: 1.2rem; color: var(textmuted); }
        .startbtn { padding: 10px 20px; fontsize: 0.9rem; minheight: 42px; background: var(glassstrong); border: 1px solid var(border); borderradius: var(radiusmd); color: var(text); fontweight: 600; cursor: pointer; transition: all 0.2s var(transitioncurve); display: inlineflex; alignitems: center; gap: 8px; }
        .startbtn:hover { bordercolor: var(borderglow); transform: translateY(2px) scale(1.03); }

        / Service Interface Styles /
        .serviceinterface { padding: 20px; maxwidth: 1200px; margin: 0 auto; animation: fadeIn 0.5s ease; }
        .interfaceheader { textalign: center; marginbottom: 25px; }
        .interfaceheader h2 { display: flex; alignitems: center; justifycontent: center; gap: 10px; marginbottom: 8px; fontsize: 1.4rem; }
        .interfaceheader p { color: var(textmuted); fontsize: 0.95rem; lineheight: 1.4; }
        .interfacecontent { background: var(glass); border: 1px solid var(border); borderradius: var(radiuslg); padding: 24px; }
        .inputsection { marginbottom: 25px; }
        .inputsection h3 { marginbottom: 15px; color: var(text); fontsize: 1.1rem; }
        .inputsection textarea, .inputsection input, .inputsection select { width: 100%; background: var(glassstrong); border: 1px solid var(border); borderradius: var(radiussm); padding: 12px; color: var(text); fontsize: 0.9rem; fontfamily: inherit; transition: bordercolor 0.2s ease; }
        .inputsection textarea:focus, .inputsection input:focus, .inputsection select:focus { outline: none; bordercolor: var(primary); }
        .inputsection textarea { resize: vertical; minheight: 120px; fontfamily: 'SF Mono', monospace; }
        .optionsgrid { display: grid; gridtemplatecolumns: repeat(autofit, minmax(200px, 1fr)); gap: 16px; margintop: 20px; }
        .optiongroup { display: flex; flexdirection: column; gap: 6px; }
        .optiongroup label { fontsize: 0.8rem; fontweight: 600; color: var(text); }
        .actionbuttons { display: flex; gap: 12px; justifycontent: center; flexwrap: wrap; margintop: 30px; }
        .primarybtn, .secondarybtn { padding: 10px 16px; borderradius: var(radiusmd); border: 1px solid var(border); fontweight: 600; fontsize: 0.85rem; cursor: pointer; transition: all 0.2s var(transitioncurve); display: inlineflex; alignitems: center; gap: 8px; minheight: 42px; }
        .primarybtn { background: lineargradient(135deg, var(primary), var(secondary)); color: white; bordercolor: var(primary); }
        .primarybtn:hover { transform: translateY(2px); boxshadow: 0 4px 15px rgba(var(primaryrgb), 0.4); }
        .secondarybtn { background: var(glassstrong); color: var(text); }
        .secondarybtn:hover { background: var(glassstrong); bordercolor: var(primary); transform: translateY(1px); }
        .resultsection { margintop: 30px; paddingtop: 20px; bordertop: 1px solid var(border); }
        .resultsection h3 { fontsize: 1rem; fontweight: 600; marginbottom: 16px; color: var(text); }
        .resultsection pre { background: rgba(0,0,0,0.4); border: 1px solid var(border); borderradius: var(radiussm); padding: 12px; margin: 12px 0; fontsize: 0.85rem; overflowx: auto; }
        .resultsection code { fontfamily: 'SF Mono', 'Fira Code', monospace; }
        .statusindicator { padding: 15px; borderradius: var(radiusmd); margin: 10px 0; display: flex; alignitems: center; gap: 10px; fontweight: 600; }
        .statusrunning { background: rgba(var(primaryrgb), 0.1); color: var(primary); border: 1px solid rgba(var(primaryrgb), 0.3); }
        .statuserror { background: rgba(239, 68, 68, 0.1); color: ef4444; border: 1px solid rgba(239, 68, 68, 0.3); }

        .tabselector { display: flex; gap: 5px; marginbottom: 20px; background: var(glass); borderradius: var(radiusmd); padding: 5px; }
        .tabbtn { background: transparent; border: none; color: var(textmuted); padding: 8px 16px; borderradius: var(radiussm); cursor: pointer; transition: all 0.2s var(transitioncurve); fontweight: 500; fontsize: 0.85rem; }
        .tabbtn.active, .tabbtn:hover { background: var(glassstrong); color: var(text); }
        .tabcontent { display: none; }
        .tabcontent.active { display: block; animation: fadeIn 0.4s ease; }
        .glasscard { background: var(glass); border: 1px solid var(border); borderradius: var(radiusmd); padding: 15px; marginbottom: 15px; }
        .sequencestats { display: flex; justifycontent: spacebetween; alignitems: center; fontsize: 0.8rem; color: var(textmuted); margintop: 10px; }

        @media (maxwidth: 768px) {
            .sidebar { width: 100vw; }
            .maincontent { marginleft: 0; }
            .welcometitle { fontsize: 1.8rem; }
            .serviceinterface { padding: 16px; }
            .interfacecontent { padding: 16px; }
        }
    </style>
</head>

<body>
    <div class="aurorabackground">
        <div class="aurora one"></div>
        <div class="aurora two"></div>
    </div>
    <div class="sidebaroverlay" id="sidebarOverlay"></div>

    <div class="container">
        <aside class="sidebar" id="sidebar" role="navigation">
            <header class="sidebarheader">
                <div class="logo">
                    <div class="logoicon" id="logoiconcontainer"></div>
                    <div class="logotext">
                        <h1>JADED</h1>
                        <p>Deep Discovery AI Platform</p>
                    </div>
                </div>
                <button class="newchatbtn" onclick="newSession()">
                    <i class="fas fahome"></i>
                    Főoldal
                </button>
            </header>
            <div class="sidebarcontent" id="sidebarContent"></div>
            <footer class="sidebarfooter">
                <p class="madeby">JADED v2.1 by Sándor Kollár</p>
            </footer>
        </aside>

        <main class="maincontent" id="mainContent">
            <header class="header">
                <button class="menutoggle" onclick="toggleSidebar()" arialabel="Menü megnyitása/bezárása">
                    <i class="fas fabars"></i>
                </button>
                <h1 class="headertitle" id="headerTitle">JADED</h1>
            </header>

            <div class="chatarea" id="messagesContainer">
                <header class="welcomescreen" id="welcomeScreen">
                    <h1 class="welcometitle">Üdv a JADED platformon!</h1>
                    <p class="welcomesubtitle">
                        A bal oldali menüből válassz egy szolgáltatást a kezdéshez. 
                        Az AlphaFold Viewer egy interaktív felület a protein szerkezet előrejelzéséhez.
                    </p>
                    <button class="startbtn" onclick="toggleSidebar()">
                        <i class="fas fabars"></i>
                        Szolgáltatások
                    </button>
                </header>
            </div>
        </main>
    </div>

    <link rel="stylesheet" href="" integrity="sha512DTOQO9RWCH3ppGqcWaEA1BIZOC6xxalwEsw9c2QQeAIftl+Vegovlnee1c9QX4TctnWMn13TZye+giMm8e2LwA==" crossorigin="anonymous" referrerpolicy="noreferrer" />
    <script src="" integrity="sha512D9gUyxqja7hBtkWpPWGt9wfb5F/sc7FpdaSMfPMrJc3CkzXPgAenPhJ4HCWJeQ30/eIs40+o8SjF9WZpBFjJ2w==" crossorigin="anonymous" referrerpolicy="noreferrer"></script>

    <script>
        //  DOM Elements 
        const getEl = (id) => document.getElementById(id);
        const sidebar = getEl('sidebar');
        const sidebarOverlay = getEl('sidebarOverlay');
        const sidebarContent = getEl('sidebarContent');
        const messagesContainer = getEl('messagesContainer');
        const headerTitle = getEl('headerTitle');
        let welcomeScreen = getEl('welcomeScreen');

        //  Theme Manager (Static BlueGreen) 
        class DynamicThemeManager {
            constructor() {
                const root = document.documentElement;
                const auroraBlobs = document.querySelectorAll('.aurorabackground .aurora');
                const colorPair = { primary: '0A61F7', secondary: '39FF14' };

                const primaryRGB = this.hexToRgb(colorPair.primary);
                root.style.setProperty('primary', colorPair.primary);
                root.style.setProperty('secondary', colorPair.secondary);
                root.style.setProperty('accent', colorPair.primary);
                root.style.setProperty('borderglow', rgba(${primaryRGB}, 0.5));
                root.style.setProperty('primaryrgb', primaryRGB);
                auroraBlobs.forEach((blob, i) => { blob.style.backgroundColor = i % 2 === 0 ? colorPair.primary : colorPair.secondary; });

                setTimeout(() => auroraBlobs.forEach(b => b.classList.add('visible')), 500);
            }
            hexToRgb = (hex) => {
                let r=0,g=0,b=0;
                if(hex.length==7){r=parseInt(hex.substring(1,3),16);g=parseInt(hex.substring(3,5),16);b=parseInt(hex.substring(5,7),16);}
                return ${r},${g},${b};
            };
        }

        //  Core UI Functions 
        function createSVGLogo() {
            getEl('logoiconcontainer').innerHTML = <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:100%;"><path d="M 30 28 C 30 50 50 72 70 72" stroke="rgba(255,255,255,0.8)" stroke-width="8" fill="none" stroke-linecap="round"/><circle cx="30" cy="72" r="6" fill="rgba(255,255,255,0.8)"/></svg>;
        }
        function toggleSidebar() { sidebar.classList.toggle('open'); sidebarOverlay.classList.toggle('active'); }
        function closeSidebar() { sidebar.classList.remove('open'); sidebarOverlay.classList.remove('active'); }
        function hideWelcome() { if (welcomeScreen) { welcomeScreen.style.display = 'none'; welcomeScreen = null; } }
        function newSession() {
            messagesContainer.innerHTML = '';
            const newWelcomeScreen = document.createElement('header');
            newWelcomeScreen.className = 'welcomescreen';
            newWelcomeScreen.id = 'welcomeScreen';
            newWelcomeScreen.innerHTML = <h1 class="welcome-title">Üdv a JADED platformon!</h1><p class="welcome-subtitle">A bal oldali menüből válassz egy szolgáltatást a kezdéshez. Az **AlphaFold Viewer** egy interaktív felület a protein szerkezet előrejelzéséhez.</p><button class="start-btn" onclick="toggleSidebar()"><i class="fas fa-bars"></i> Szolgáltatások</button>;
            messagesContainer.appendChild(newWelcomeScreen);
            welcomeScreen = getEl('welcomeScreen');
            headerTitle.textContent = 'JADED';
            closeSidebar();
        }

        //  Service Loading 
        function loadServices() {
            const servicesData = {
                "Tudományos Modellezés": {
                    icon: "fadna",
                    services: {
                        "AlphaFold Viewer": "Protein szerkezet predikció",
                        "AlphaGenome Viewer": "Genomikai elemzés és vizualizáció",
                        "3D Viewer": "3D modellek és adathalmazok megjelenítése"
                    }
                },
                "Kutatási Eszközök": {
                    icon: "famicroscope",
                    services: {
                        "Deep Search": "Mélyreható tudományos keresés",
                        "Services Navigation": "Szolgáltatások közötti navigáció"
                    }
                }
            };

            sidebarContent.innerHTML = '';
            for (const categoryName in servicesData) {
                const category = servicesData[categoryName];
                let servicesHTML = Object.entries(category.services).map(([serviceName, description]) => 
                    <div class="serviceitem" onclick="selectService('${escapeHtml(serviceName).replace(/'/g, "\\'")}', '${escapeHtml(description).replace(/'/g, "\\'")}')">
                        <div class="serviceicon"><i class="fas faflask"></i></div>
                        <div class="serviceinfo">
                            <h4>${escapeHtml(serviceName)}</h4>
                            <p>${escapeHtml(description)}</p>
                        </div>
                    </div>
                ).join('');

                const categoryDiv = document.createElement('div');
                categoryDiv.className = 'servicecategory';
                categoryDiv.innerHTML = 
                    <div class="categoryheader" onclick="toggleCategory(this)">
                        <div class="categorytitle"><i class="fas ${category.icon}"></i><span>${categoryName}</span></div>
                        <i class="fas fachevrondown"></i>
                    </div>
                    <div class="categoryservices"><div>${servicesHTML}</div></div>;
                sidebarContent.appendChild(categoryDiv);
            }
        }
        function toggleCategory(header) {
            const categoryServices = header.nextElementSibling;
            const chevron = header.querySelector('.fachevrondown');
            categoryServices.classList.toggle('open');
            chevron.style.transform = categoryServices.classList.contains('open') ? 'rotate(180deg)' : 'rotate(0deg)';
        }
        function selectService(serviceName, description) { 
            hideWelcome();
            headerTitle.textContent = serviceName;
            showServiceInterface(serviceName, description); 
            closeSidebar(); 
        }

        //  Service Interface Rendering 
        function showServiceInterface(serviceName, description) {
            if (serviceName.includes('AlphaFold')) {
                showAlphaFoldInterface();
            } else {
                showStaticViewerInterface(serviceName, description);
            }
        }

        function showAlphaFoldInterface() {
            const interfaceHTML = 
                <div class="serviceinterface">
                    <div class="interfaceheader">
                        <h2><i class="fas fadna accent"></i> AlphaFold Protein Szerkezet Predikció</h2>
                        <p>Adjon meg egy protein szekvenciát a 3D szerkezetének előrejelzéséhez a backend mock szolgáltatásával.</p>
                    </div>
                    <div class="interfacecontent">
                        <div class="tabselector">
                            <button class="tabbtn active">Szekvencia Bevitel</button>
                        </div>
                        <div class="tabcontent active">
                            <div class="inputsection glasscard">
                                <h3>Protein Szekvencia</h3>
                                <textarea id="proteinSequence" placeholder="Írja be a protein szekvenciát (pl. 'GSWTEHKPDE')..." rows="8"></textarea>
                                <div class="sequencestats">
                                    <span id="sequencelength">Hossz: 0</span>
                                </div>
                            </div>
                        </div>
                        <div class="actionbuttons">
                            <button class="primarybtn" onclick="runAlphaFoldPrediction()">
                                <i class="fas farocket"></i> Predikció Indítása
                            </button>
                        </div>
                        </div>
                </div>;
            messagesContainer.innerHTML = interfaceHTML;
            getEl('proteinSequence').addEventListener('input', updateSequenceStats);
        }

        function showStaticViewerInterface(serviceName, description) {
            const icons = {
                "AlphaGenome Viewer": "famicroscope",
                "3D Viewer": "facube",
                "Deep Search": "fasearch",
                "Services Navigation": "facompass"
            };
            const iconClass = icons[serviceName] || 'fawindowmaximize';
            const interfaceHTML = 
                <div class="serviceinterface">
                    <div class="interfaceheader">
                         <h2><i class="fas ${iconClass} accent"></i> ${serviceName}</h2>
                         <p>${description}</p>
                    </div>
                    <div class="interfacecontent">
                        <p>Ez a felület a(z) <strong>${serviceName}</strong> szolgáltatás megjelenítésére szolgál. A jelenlegi backend konfigurációban ez egy statikus nézet.</p>
                    </div>
                </div>;
            messagesContainer.innerHTML = interfaceHTML;
        }

        //  Backend Communication & Logic 
        function updateSequenceStats() { 
            const seq = getEl('proteinSequence').value;
            getEl('sequencelength').textContent = Hossz: ${seq.replace(/[^A-Za-z]/g, '').length};
        }

        async function runAlphaFoldPrediction() {
            const sequence = getEl('proteinSequence').value.trim();
            if (!sequence) {
                displayError("A szekvencia nem lehet üres.");
                return;
            }

            showProgress('Predikció küldése a szervernek...');

            try {
                const response = await fetch('/predict', {
                    method: 'POST',
                    headers: { 'ContentType': 'application/json' },
                    body: JSON.stringify({ sequence: sequence })
                });

                if (!response.ok) {
                    const errorData = await response.json();
                    throw new Error(errorData.message || HTTP hiba: ${response.status});
                }

                const result = await response.json();
                displayResults(result, 'AlphaFold Predikciós Eredmény');

            } catch (error) {
                console.error("Hiba a predikció során:", error);
                displayError(Hiba történt: ${error.message});
            }
        }

        //  Result Display 
        function showProgress(message) {
            const container = document.querySelector('.serviceinterface .interfacecontent');
            if (!container) return;

            let resultSection = container.querySelector('.resultsection');
            if (!resultSection) {
                resultSection = document.createElement('div');
                resultSection.className = 'resultsection';
                container.appendChild(resultSection);
            }

            resultSection.innerHTML = <div class="status-indicator status-running"><i class="fas fa-spinner fa-spin"></i><span>${message}</span></div>;
        }

        function displayResults(data, title) {
            const container = document.querySelector('.serviceinterface .interfacecontent');
            if (!container) return;

            let resultSection = container.querySelector('.resultsection');
            if (!resultSection) {
                resultSection = document.createElement('div');
                resultSection.className = 'resultsection';
                container.appendChild(resultSection);
            }

            const resultHTML = 
                <h3><i class="fas facheckcircle" style="color: 39FF14;"></i> ${title}</h3>
                <p>A szerver a következő (mock) adatokat küldte vissza:</p>
                <pre><code>${escapeHtml(JSON.stringify(data, null, 2))}</code></pre>
                <div class="actionbuttons">
                    <button class="secondarybtn" onclick="showAlphaFoldInterface()">
                        <i class="fas faredo"></i> Új Predikció
                    </button>
                </div>;
            resultSection.innerHTML = resultHTML;
            if (typeof hljs !== 'undefined') { hljs.highlightAll(); }
        }

        function displayError(message) {
            const container = document.querySelector('.serviceinterface .interfacecontent');
            if (!container) return;

             let resultSection = container.querySelector('.resultsection');
            if (!resultSection) {
                resultSection = document.createElement('div');
                resultSection.className = 'resultsection';
                container.appendChild(resultSection);
            }

            resultSection.innerHTML = <div class="status-indicator status-error"><i class="fas fa-exclamation-triangle"></i> ${escapeHtml(message)}</div>;
        }

        //  Utilities & Event Listeners 
        function escapeHtml(text) { 
            const div = document.createElement('div'); 
            div.textContent = String(text); 
            return div.innerHTML; 
        }
        function setupEventListeners() {
            sidebarOverlay.addEventListener('click', closeSidebar);
        }

        //  App Initialization 
        document.addEventListener('DOMContentLoaded', () => {
            console.log('🚀 JADED Platform Initialized');
            window.themeManager = new DynamicThemeManager();
            createSVGLogo();
            setupEventListeners();
            loadServices();
        });
    </script>
</body>
</html>



