Itt van egy tiszta CSS sablon, amely az eredeti HTML design stílusát és látványvilágát tartalmazza:

css
/* ====== JADED PLATFORM DESIGN TEMPLATE ====== */

/* FONT IMPORT */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

/* CSS CUSTOM PROPERTIES (VARIABLES) */
:root {
    /* COLOR PALETTE */
    --primary: #0A61F7;              /* Fő kék szín */
    --secondary: #39FF14;            /* Zöld akcent */
    --accent: #0A61F7;               /* Akcent szín */
    --border-glow: rgba(10, 97, 247, 0.5);
    --primary-rgb: 10, 97, 247;
    --secondary-rgb: 57, 255, 20;

    /* BACKGROUND COLORS */
    --bg: #000000;                   /* Főháttér - fekete */
    --surface: rgba(10, 10, 10, 0.7); /* Felületek háttere */
    --glass: rgba(255, 255, 255, 0.02); /* Üveg effekt */
    --glass-strong: rgba(255, 255, 255, 0.05);
    --border: rgba(255, 255, 255, 0.08);

    /* TEXT COLORS */
    --text: #f0f0f0;                 /* Fő szöveg szín */
    --text-muted: #94a3b8;           /* Halvány szöveg */

    /* BORDER RADIUS */
    --radius-lg: 24px;
    --radius-md: 16px;
    --radius-sm: 12px;

    /* SHADOWS & EFFECTS */
    --shadow: 0 12px 48px rgba(0, 0, 0, 0.6);
    --transition-curve: cubic-bezier(0.25, 0.8, 0.25, 1);
    --transition-color-slow: 15s ease-in-out;
}

/* RESET & BASE STYLES */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    -webkit-tap-highlight-color: transparent;
}

html {
    height: 100%;
    height: -webkit-fill-available;
    scroll-behavior: smooth;
}

body {
    font-family: 'Inter', sans-serif;
    background: var(--bg);
    color: var(--text);
    min-height: 100vh;
    min-height: -webkit-fill-available;
    overflow-x: hidden;
    -webkit-font-smoothing: antialiased;
    font-size: 15px;
}

/* ANIMATED BACKGROUND */
.aurora-background {
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    pointer-events: none;
    z-index: -1;
    overflow: hidden;
    will-change: transform;
}

.aurora {
    position: absolute;
    border-radius: 50%;
    mix-blend-mode: screen;
    filter: blur(120px);
    opacity: 0;
    transition: background-color var(--transition-color-slow), opacity 8s ease-in-out;
    animation: pulse 30s ease-in-out infinite alternate;
    will-change: transform, opacity;
}

.aurora.visible {
    opacity: 0.3;
}

.aurora.one {
    width: 80vmax;
    height: 80vmax;
    background-color: var(--primary);
    animation-name: move-one, pulse;
    animation-duration: 1200s, 35s;
    animation-timing-function: linear, ease-in-out;
    animation-iteration-count: infinite, infinite;
    animation-direction: alternate, alternate;
}

.aurora.two {
    width: 70vmax;
    height: 70vmax;
    background-color: var(--secondary);
    animation-name: move-two, pulse;
    animation-duration: 1050s, 40s;
    animation-timing-function: linear, ease-in-out;
    animation-iteration-count: infinite, infinite;
    animation-direction: alternate, alternate;
}

@keyframes move-one {
    from { transform: translate(-20vw, -20vh) scale(1); }
    to { transform: translate(50vw, 80vh) scale(1.2); }
}

@keyframes move-two {
    from { transform: translate(80vw, 30vh) scale(1); }
    to { transform: translate(-10vw, 60vh) scale(1.3); }
}

@keyframes pulse {
    from { opacity: 0.2; }
    to { opacity: 0.4; }
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(15px); }
    to { opacity: 1; transform: translateY(0); }
}

/* GRADIENT TEXT EFFECTS */
.gradient-text {
    background: linear-gradient(135deg, var(--primary), var(--secondary));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

/* GLASS MORPHISM CARDS */
.glass-card {
    background: var(--glass);
    border: 1px solid var(--border);
    border-radius: var(--radius-md);
    padding: 20px;
    backdrop-filter: blur(60px) saturate(180%);
    transition: all 0.3s var(--transition-curve);
}

.glass-card:hover {
    background: var(--glass-strong);
    border-color: var(--border-glow);
    transform: translateY(-2px);
    box-shadow: var(--shadow);
}

/* BUTTON STYLES */
.btn-primary {
    background: linear-gradient(135deg, var(--primary), var(--secondary));
    border: 1px solid var(--primary);
    color: white;
    padding: 12px 24px;
    border-radius: var(--radius-md);
    font-weight: 600;
    font-size: 0.9rem;
    cursor: pointer;
    transition: all 0.3s var(--transition-curve);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    text-decoration: none;
}

.btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 25px rgba(var(--primary-rgb), 0.4);
}

.btn-secondary {
    background: var(--glass-strong);
    border: 1px solid var(--border);
    color: var(--text);
    padding: 12px 24px;
    border-radius: var(--radius-md);
    font-weight: 600;
    font-size: 0.9rem;
    cursor: pointer;
    transition: all 0.3s var(--transition-curve);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    text-decoration: none;
}

.btn-secondary:hover {
    background: var(--glass-strong);
    border-color: var(--primary);
    transform: translateY(-1px);
}

/* FORM ELEMENTS */
.form-input, .form-textarea, .form-select {
    width: 100%;
    background: var(--glass-strong);
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    padding: 12px 16px;
    color: var(--text);
    font-size: 0.9rem;
    font-family: inherit;
    transition: border-color 0.2s ease;
}

.form-input:focus, .form-textarea:focus, .form-select:focus {
    outline: none;
    border-color: var(--primary);
    box-shadow: 0 0 0 3px rgba(var(--primary-rgb), 0.1);
}

.form-textarea {
    resize: vertical;
    min-height: 120px;
    font-family: 'SF Mono', monospace;
}

/* SIDEBAR STYLES */
.sidebar {
    width: 260px;
    background: var(--surface);
    backdrop-filter: blur(60px) saturate(180%);
    border-right: 1px solid var(--border);
    height: 100vh;
    position: fixed;
    left: 0;
    top: 0;
    z-index: 1000;
    transform: translateX(-100%);
    transition: transform 0.4s var(--transition-curve);
}

.sidebar.open {
    transform: translateX(0);
}

/* NAVIGATION ITEMS */
.nav-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 16px;
    color: var(--text);
    text-decoration: none;
    border-radius: var(--radius-sm);
    margin: 4px 8px;
    transition: all 0.2s var(--transition-curve);
    border-left: 2px solid transparent;
}

.nav-item:hover {
    background: var(--glass-strong);
    border-left-color: var(--primary);
    transform: translateX(4px);
}

.nav-item.active {
    background: var(--glass-strong);
    border-left-color: var(--primary);
    color: var(--primary);
}

/* ICON CONTAINERS */
.icon-container {
    width: 32px;
    height: 32px;
    background: var(--glass-strong);
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--accent);
    transition: all 0.3s var(--transition-curve);
}

.icon-container:hover {
    transform: scale(1.1) rotate(5deg);
    border-color: var(--border-glow);
    box-shadow: 0 4px 10px var(--border-glow);
}

/* HEADER STYLES */
.page-header {
    background: var(--surface);
    backdrop-filter: blur(60px) saturate(180%);
    border-bottom: 1px solid var(--border);
    padding: 16px 24px;
    position: sticky;
    top: 0;
    z-index: 100;
}

.page-title {
    font-size: 1.5rem;
    font-weight: 700;
    background: linear-gradient(135deg, var(--primary), var(--secondary));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

/* STATUS INDICATORS */
.status-success {
    background: rgba(34, 197, 94, 0.1);
    color: #22c55e;
    border: 1px solid rgba(34, 197, 94, 0.3);
    padding: 12px 16px;
    border-radius: var(--radius-md);
    display: flex;
    align-items: center;
    gap: 8px;
}

.status-error {
    background: rgba(239, 68, 68, 0.1);
    color: #ef4444;
    border: 1px solid rgba(239, 68, 68, 0.3);
    padding: 12px 16px;
    border-radius: var(--radius-md);
    display: flex;
    align-items: center;
    gap: 8px;
}

.status-warning {
    background: rgba(251, 191, 36, 0.1);
    color: #fbbf24;
    border: 1px solid rgba(251, 191, 36, 0.3);
    padding: 12px 16px;
    border-radius: var(--radius-md);
    display: flex;
    align-items: center;
    gap: 8px;
}

.status-info {
    background: rgba(var(--primary-rgb), 0.1);
    color: var(--primary);
    border: 1px solid rgba(var(--primary-rgb), 0.3);
    padding: 12px 16px;
    border-radius: var(--radius-md);
    display: flex;
    align-items: center;
    gap: 8px;
}

/* CODE BLOCKS */
.code-block {
    background: rgba(0,0,0,0.4);
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    padding: 16px;
    font-family: 'SF Mono', 'Fira Code', monospace;
    font-size: 0.85rem;
    overflow-x: auto;
    color: var(--text);
}

/* LOADING SPINNER */
.loading-spinner {
    display: inline-block;
    width: 20px;
    height: 20px;
    border: 2px solid var(--border);
    border-radius: 50%;
    border-top-color: var(--primary);
    animation: spin 1s ease-in-out infinite;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

/* RESPONSIVE DESIGN */
@media (max-width: 768px) {
    .sidebar {
        width: 100vw;
    }

    .page-title {
        font-size: 1.2rem;
    }

    .btn-primary, .btn-secondary {
        padding: 10px 16px;
        font-size: 0.85rem;
    }

    .glass-card {
        padding: 16px;
    }
}

@media (max-width: 480px) {
    body {
        font-size: 14px;
    }

    .page-header {
        padding: 12px 16px;
    }

    .glass-card {
        padding: 12px;
    }
}

/* UTILITY CLASSES */
.text-center { text-align: center; }
.text-left { text-align: left; }
.text-right { text-align: right; }

.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-center { justify-content: center; }
.justify-between { justify-content: space-between; }
.gap-2 { gap: 8px; }
.gap-4 { gap: 16px; }
.gap-6 { gap: 24px; }

.mt-2 { margin-top: 8px; }
.mt-4 { margin-top: 16px; }
.mt-6 { margin-top: 24px; }
.mb-2 { margin-bottom: 8px; }
.mb-4 { margin-bottom: 16px; }
.mb-6 { margin-bottom: 24px; }

.p-2 { padding: 8px; }
.p-4 { padding: 16px; }
.p-6 { padding: 24px; }

.w-full { width: 100%; }
.h-full { height: 100%; }

.opacity-50 { opacity: 0.5; }
.opacity-75 { opacity: 0.75; }

/* ACCENT COLORS */
.accent-text { color: var(--accent); }
.accent-bg { background-color: var(--accent); }
.accent-border { border-color: var(--accent); }

/* HOVER EFFECTS */
.hover-lift:hover {
    transform: translateY(-2px);
    transition: transform 0.2s var(--transition-curve);
}

.hover-glow:hover {
    box-shadow: 0 0 20px rgba(var(--primary-rgb), 0.3);
    transition: box-shadow 0.3s var(--transition-curve);
}


